function maxLPSWithEdits(s, k) {
  const n = s.length;
  const dp = Array.from({length: n}, () => Array.from({length: n}, () => Array(k+1).fill(0)));
  for (let i=0;i<n;i++) for (let t=0;t<=k;t++) dp[i][i][t] = 1;
  for (let len=2; len<=n; len++) {
    for (let i=0; i+len-1<n; i++) {
      const j = i+len-1;
      for (let t=0; t<=k; t++) {
        let best = Math.max(dp[i+1][j][t], dp[i][j-1][t]);
        if (s[i] === s[j]) best = Math.max(best, dp[i+1][j-1][t] + 2);
        if (t >= 1) best = Math.max(best, dp[i+1][j-1][t-1] + 2);
        if (t >= 2) best = Math.max(best, dp[i+1][j-1][t-2] + 2);
        dp[i][j][t] = best;
      }
    }
  }
  return dp[0][n-1][k];
